    \makebox[1em]{a)}
    \centerline{\includegraphics[scale=0.25]{theory_compare1.png}}
    \makebox[1em]{c)}
    \centerline{\includegraphics[scale=0.25]{theory_gam.png}}
    \end{minipage}
    \hspace{50pt}
